-- cpd-migration: additive
-- pro-d68 (Plan fb-path; contract §2.2 "Feedback item", §4.4, §7.6 step 3a): what the poll last read of a pull request's review
-- comments. `updated_at` is GitHub's `updatedAt` at that read, `feedback` the JSON array of the open items; both NULL = never read.
-- The `pull_requests` history triggers are regenerated by the runner's reconcile (K4).
ALTER TABLE pull_requests ADD COLUMN updated_at TEXT;
ALTER TABLE pull_requests ADD COLUMN feedback TEXT;
